#!/usr/bin/env bash
set -eu
total() {
  local price=$1 quantity=$2
  [[ $price =~ ^[0-9]{1,6}$ && $quantity =~ ^[0-9]{1,6}$ ]] || return 1
  printf '%s\n' "$((10#$price * 10#$quantity))"
}
total 12 3
total 12 0
if ! total 12 -1; then printf '%s\n' 'Invalid input rejected'; fi

