#!/usr/bin/env bash
greet() {
  local name=$1
  printf 'Hello, %s!\n' "$name"
}
add() {
  printf '%s\n' "$(( $1 + $2 ))"
}
nonempty_or_fail() {
  [ -n "$1" ]
}
greet 'Bash'
add 5 7
if nonempty_or_fail 'text'; then printf '%s\n' 'accepted'; fi
if ! nonempty_or_fail ''; then printf '%s\n' 'rejected'; fi

